use spacejam_core::{service::ServiceAccount, statistic::Statistics};

#[test]
fn test_service_account() {
    let account = ServiceAccount::default();
    let encoded = codec::encode(&account).unwrap();
    assert_eq!(encoded, vec![0; 59]);
    let decoded = codec::decode::<ServiceAccount>(&encoded).unwrap();
    assert_eq!(account, decoded);
}

#[test]
fn test_service_statistics() {
    let data = "";
    let data = hex::decode(data).unwrap();

    let stats = codec::decode::<Statistics>(&data).unwrap();
    println!("{:#?}", stats);

    let encoded = codec::encode(&stats).unwrap();
    assert_eq!(encoded, data);
}

